//! Golden test for `evaluate.rs`: the same random city states and the same
//! call order as `reference/gold/evaluate_cases.cpp`, which ran the ORIGINAL
//! C++ functions. The expected output is `tests/data/evaluate_gold.txt`
//! (generated by that harness: `reference/build-harness.sh` then run the
//! binary). Every line must match exactly.

use micropolis_core::simulation::Simulation;
use std::fmt::Write;

const GOLD: &str = include_str!("data/evaluate_gold.txt");
const NCASES: i64 = 200;
const LV_W: i32 = 60;
const LV_H: i32 = 50;

/// Same generator as the C++ harness.
struct Gen(u64);

impl Gen {
    fn next(&mut self) -> u64 {
        self.0 = self
            .0
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        self.0 >> 33
    }

    fn pick(&mut self, lo: i64, hi: i64) -> i64 {
        lo + (self.next() % ((hi - lo + 1) as u64)) as i64
    }
}

fn run_cases() -> String {
    let mut g = Gen(20_240_611);
    let mut s = Simulation::new(120, 100);
    let mut out = String::new();
    for i in 0..NCASES {
        // ---- state (order of the picks matches the C++ harness) ----
        s.res_pop = g.pick(0, if i % 10 == 9 { 32767 } else { 4000 }) as i16;
        s.com_pop = g.pick(0, if i % 10 == 9 { 32767 } else { 800 }) as i16;
        s.ind_pop = g.pick(0, if i % 10 == 9 { 32767 } else { 800 }) as i16;
        s.fire_pop = g.pick(0, if i % 7 == 6 { 32767 } else { 120 }) as i16;
        s.road_total = g.pick(0, 2000) as i16;
        s.rail_total = g.pick(0, 300) as i16;
        s.police_station_pop = g.pick(0, 40) as i16;
        s.fire_station_pop = g.pick(0, 40) as i16;
        s.hospital_pop = g.pick(0, 60) as i16;
        s.stadium_pop = g.pick(0, 4) as i16;
        s.seaport_pop = g.pick(0, 3) as i16;
        s.airport_pop = g.pick(0, 3) as i16;
        s.coal_power_pop = g.pick(0, 5) as i16;
        s.nuclear_power_pop = g.pick(0, 3) as i16;
        s.crime_average = g.pick(0, 255) as i16;
        s.pollution_average = g.pick(0, 255) as i16;
        s.land_value_average = g.pick(0, 255) as i16;
        s.city_tax = g.pick(0, 20) as i16;
        s.city_pop = g.pick(0, 600_000);
        let mode = g.pick(0, 9);
        s.city_pop_delta = if mode == 0 {
            0
        } else if mode == 1 {
            s.city_pop
        } else {
            g.pick(-s.city_pop, s.city_pop)
        };
        s.powered_zone_count = g.pick(0, 400) as i16;
        s.unpowered_zone_count = g.pick(0, 400) as i16;
        s.res_valve = g.pick(-2100, 2100) as i16;
        s.com_valve = g.pick(-2000, 1600) as i16;
        s.ind_valve = g.pick(-2000, 1600) as i16;
        s.res_cap = g.pick(0, 4) == 0;
        s.com_cap = g.pick(0, 4) == 0;
        s.ind_cap = g.pick(0, 4) == 0;
        s.road_effect = g.pick(0, 32) as i32;
        s.police_effect = g.pick(0, 1000) as i32;
        s.fire_effect = g.pick(0, 1000) as i32;
        s.city_score = g.pick(0, 1000) as i16;
        let mut table = [0i16; 10];
        for slot in table.iter_mut().take(7) {
            *slot = g.pick(0, 255) as i16;
        }
        s.total_pop = if g.pick(0, 4) == 0 {
            0
        } else {
            g.pick(1, 32767) as i16
        };
        for x in 0..LV_W {
            for y in 0..LV_H {
                let v = if g.pick(0, 2) == 0 { 0 } else { g.pick(0, 255) };
                s.land_value_map.set(x, y, v as u8);
            }
        }
        for x in 0..LV_W {
            for y in 0..LV_H {
                let v = g.pick(0, 255);
                s.traffic_density_map.set(x, y, v as u8);
            }
        }
        let seed = 1000 + i;

        // ---- A: census-only functions ----
        let pop = s.get_population();
        let cls = s.get_city_class(s.city_pop) as i64;
        let unemp = s.get_unemployment();
        let fire = s.get_fire_severity();
        s.get_assessed_value();
        let traffic = s.get_traffic_average();
        writeln!(
            out,
            "A {pop} {cls} {unemp} {fire} {} {traffic}",
            s.city_assessed_value
        )
        .unwrap();

        // ---- S: score ----
        s.get_score(&table);
        writeln!(out, "S {} {}", s.city_score, s.city_score_delta).unwrap();

        // ---- P: population and class ----
        s.do_pop_num();
        writeln!(
            out,
            "P {} {} {}",
            s.city_pop, s.city_pop_delta, s.city_class as i64
        )
        .unwrap();

        // ---- V: mayor's approval ----
        s.rng.seed(seed as i32);
        s.do_votes();
        writeln!(out, "V {} {}", s.city_yes, s.rng.random16()).unwrap();

        // ---- D: doProblems (computes its own table) ----
        s.rng.seed((seed + 1000) as i32);
        let mut t2 = [0i16; 10];
        s.do_problems(&mut t2);
        write!(out, "D").unwrap();
        for v in t2 {
            write!(out, " {v}").unwrap();
        }
        for o in s.problem_order {
            write!(out, " o{o}").unwrap();
        }
        for v in s.problem_votes {
            write!(out, " v{v}").unwrap();
        }
        writeln!(out, " r{}", s.rng.random16()).unwrap();

        // ---- W: voteProblems on a given table ----
        s.rng.seed((seed + 2000) as i32);
        s.vote_problems(&table);
        write!(out, "W").unwrap();
        for v in s.problem_votes {
            write!(out, " {v}").unwrap();
        }
        writeln!(out, " r{}", s.rng.random16()).unwrap();

        // ---- C: accessors on the problem order ----
        write!(out, "C {}", s.count_problems()).unwrap();
        for k in 0..4 {
            write!(
                out,
                " {} {}",
                s.get_problem_number(k),
                s.get_problem_votes(k)
            )
            .unwrap();
        }
        writeln!(
            out,
            " {} {}",
            s.get_problem_number(-1),
            s.get_problem_votes(4)
        )
        .unwrap();

        // ---- E: whole evaluation ----
        s.rng.seed((seed + 3000) as i32);
        s.eval_changed = false;
        s.city_evaluation();
        write!(
            out,
            "E {} {} {} {} {} {} {} {} {}",
            s.city_yes,
            s.city_score,
            s.city_score_delta,
            s.city_pop,
            s.city_pop_delta,
            s.city_class as i64,
            s.city_assessed_value,
            s.traffic_average,
            s.eval_changed as i64
        )
        .unwrap();
        for v in s.problem_votes {
            write!(out, " v{v}").unwrap();
        }
        for o in s.problem_order {
            write!(out, " o{o}").unwrap();
        }
        writeln!(out, " r{}", s.rng.random16()).unwrap();
    }
    out
}

#[test]
fn evaluation_matches_original_cpp_line_by_line() {
    let got = run_cases();
    let want: Vec<&str> = GOLD.lines().collect();
    let got_lines: Vec<&str> = got.lines().collect();
    assert_eq!(got_lines.len(), want.len(), "number of output lines");
    for (n, (g, w)) in got_lines.iter().zip(want.iter()).enumerate() {
        assert_eq!(g, w, "line {} differs", n + 1);
    }
}
